class Solution {
public:
    long long countPalindromePaths(vector<int>& parent, string s) {
        int n = parent.size();
        vector<vector<pair<int, int>>> adj(n);
        for (int i = 1; i < n; ++i) {
            adj[parent[i]].push_back({i, 1 << (s[i] - 'a')});
        }
        vector<int> mask(n, 0);
        vector<pair<int, int>> stack = {{0, 0}};
        while (!stack.empty()) {
            auto [u, m] = stack.back();
            stack.pop_back();
            mask[u] = m;
            for (auto& edge : adj[u]) {
                stack.push_back({edge.first, m ^ edge.second});
            }
        }
        unordered_map<int, int> counts;
        for (int m : mask) counts[m]++;
        long long ans = 0;
        for (auto& entry : counts) {
            int m = entry.first;
            long long cnt = entry.second;
            ans += cnt * (cnt - 1) / 2;
            for (int i = 0; i < 26; ++i) {
                int target = m ^ (1 << i);
                if (target > m && counts.count(target)) {
                    ans += cnt * counts[target];
                }
            }
        }
        return ans;
    }
};

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Solution {
    public long countPalindromePaths(List<Integer> parent, String s) {
        int n = parent.size();
        List<List<int[]>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int i = 1; i < n; i++) {
            adj.get(parent.get(i)).add(new int[]{i, 1 << (s.charAt(i) - 'a')});
        }
        int[] mask = new int[n];
        List<int[]> stack = new ArrayList<>();
        stack.add(new int[]{0, 0});
        while (!stack.isEmpty()) {
            int[] top = stack.remove(stack.size() - 1);
            int u = top[0], m = top[1];
            mask[u] = m;
            for (int[] edge : adj.get(u)) {
                stack.add(new int[]{edge[0], m ^ edge[1]});
            }
        }
        Map<Integer, Integer> counts = new HashMap<>();
        for (int m : mask) counts.put(m, counts.getOrDefault(m, 0) + 1);
        long ans = 0;
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            int m = entry.getKey();
            long cnt = entry.getValue();
            ans += cnt * (cnt - 1) / 2;
            for (int i = 0; i < 26; i++) {
                int target = m ^ (1 << i);
                if (target > m && counts.containsKey(target)) {
                    ans += cnt * counts.get(target);
                }
            }
        }
        return ans;
    }
}

