var countPalindromePaths = function(parent, s) {
    const n = parent.length;
    const adj = Array.from({ length: n }, () => []);
    for (let i = 1; i < n; i++) {
        adj[parent[i]].push([i, 1 << (s.charCodeAt(i) - 97)]);
    }
    const mask = new Array(n).fill(0);
    const stack = [[0, 0]];
    while (stack.length > 0) {
        const [u, m] = stack.pop();
        mask[u] = m;
        for (const [v, bit] of adj[u]) {
            stack.push([v, m ^ bit]);
        }
    }
    const counts = new Map();
    for (const m of mask) {
        counts.set(m, (counts.get(m) || 0) + 1);
    }
    let ans = 0;
    for (const [m, cnt] of counts.entries()) {
        ans += (cnt * (cnt - 1)) / 2;
        for (let i = 0; i < 26; i++) {
            const target = m ^ (1 << i);
            if (target > m && counts.has(target)) {
                ans += cnt * counts.get(target);
            }
        }
    }
    return ans;
};
